{
  "unit": 48,
  "font": "serif",
  "points": {
    "A": {"at": [0, 0], "label": "A", "labelDir": "nw", "dot": true},
    "D": {"at": [4, 0], "label": "D", "labelDir": "ne", "dot": true},
    "B": {"at": [-1, -2], "label": "B", "labelDir": "sw", "dot": true},
    "C": {"at": [3, -2], "label": "C", "labelDir": "se", "dot": true},
    "E": {"at": [5, 2], "label": "E", "labelDir": "ne", "dot": true},
    "M": {"mid": ["A", "D"], "label": "M", "labelDir": "n", "dot": true},
    "N": {"along": {"from": "B", "to": "C", "t": 0.25}, "label": "N", "labelDir": "s", "dot": true}
  },
  "elements": [
    {"type": "polygon", "points": ["A", "B", "C", "D"]},
    {"type": "segment", "from": "D", "to": "E", "style": "dashed"},
    {"type": "segment", "from": "B", "to": "M", "style": "dashed"},
    {"type": "segment", "from": "B", "to": "E", "style": "dotted"},
    {"type": "segment", "from": "B", "to": "N", "arrow": "end", "label": {"text": "a", "side": "auto"}},
    {"type": "arrow", "from": "C", "to": "D", "kind": "pointer", "label": "b", "labelAt": "mid"}
  ]
}

